export type RepoStatus =
  | 'STUDY_ONLY'
  | 'ADD_STUDY_EDU'
  | 'PENDING_RELEASE'
  | 'PENDING_STARS'
  | 'PENDING_EDU_REVIEW'
  | 'PENDING_STARS_AND_RELEASE'
  | 'PENDING_TOPIC_UNKNOWN'
  | 'B68_TRACKED';

export interface RepositoryItem {
  id: string;
  name: string;
  module: string;
  status: RepoStatus;
  stars: number;
  starsSource: string;
  releaseDate?: string;
  releaseSource?: string;
  url: string;
  harnessLayer:
    | 'Layer 1: Host Sandbox & Execution'
    | 'Layer 2: MCP Tool Contracts & Schema'
    | 'Layer 3: Memory & Context Windows'
    | 'Layer 4: Agent Orchestrator & Planner'
    | 'Layer 5: Safety, Guardrails & Evaluation'
    | 'Serving & Inference Engine'
    | 'Core Model & Training'
    | 'Foundations & Math';
  description: string;
  keywords: string[];
  correlationScore: number; // 70 to 100
  isHarnessStack: boolean;
  notes?: string;
}

